_IAST_LATIN_MARKS = frozenset("āīūṛṝḷṅñṭḍṇśṣṃṁḥ")


def _script_config(
    vowels: tuple[str, ...],
    matras: tuple[str, ...],
    consonants: tuple[str, ...],
    virama: str,
    anusvara: str,
    visarga: str,
    avagraha: str,
) -> dict[str, Any]:
    return {
        "vowels": dict(zip(_IAST_VOWELS, vowels)),
        "matras": dict(zip(_IAST_VOWELS, matras)),
        "consonants": dict(zip(_IAST_CONSONANTS, consonants)),
        "virama": virama,
        "anusvara": anusvara,
        "visarga": visarga,
        "avagraha": avagraha,
    }


