_LANG_SCRIPT = {
    "hi": "Devanagari", "mr": "Devanagari", "ne": "Devanagari", "sa": "Devanagari",
    "gu": "Gujarati", "bn": "Bengali", "ta": "Tamil", "te": "Telugu",
    "kn": "Kannada", "ml": "Malayalam", "pa": "Gurmukhi", "or": "Oriya",
}
_INDIC_SCRIPT_RANGES = {
    "Devanagari": ((0x0900, 0x097F), (0x1CD0, 0x1CFF), (0xA8E0, 0xA8FF)),
    "Bengali": ((0x0980, 0x09FF),), "Gurmukhi": ((0x0A00, 0x0A7F),),
    "Gujarati": ((0x0A80, 0x0AFF),), "Oriya": ((0x0B00, 0x0B7F),),
    "Tamil": ((0x0B80, 0x0BFF),), "Telugu": ((0x0C00, 0x0C7F),),
    "Kannada": ((0x0C80, 0x0CFF),), "Malayalam": ((0x0D00, 0x0D7F),),
}


def _tokenize_iast(value: str) -> list[tuple[str, str]]:
    text = unicodedata.normalize("NFC", value).lower().replace("ṁ", "ṃ")
    tokens: list[tuple[str, str]] = []
    index = 0
    while index < len(text):
        matched = ""
        for candidate in _IAST_LONG_TOKENS:
            if text.startswith(candidate, index):
                matched = candidate
                break
        if matched:
            kind = "vowel" if matched in _IAST_VOWELS else "consonant"
            tokens.append((kind, matched))
            index += len(matched)
            continue
        character = text[index]
        if character == "ṃ":
            tokens.append(("anusvara", character))
        elif character == "ḥ":
            tokens.append(("visarga", character))
        elif character in {"'", "’", "ʼ", "ऽ"}:
            tokens.append(("avagraha", character))
        else:
            tokens.append(("other", character))
        index += 1
    return tokens


def _fallback_iast_to_indic(value: str, lang: str) -> str:
    script = _LANG_SCRIPT.get(lang, "")
    config = _INDIC_SCRIPT_CONFIGS.get(script)
    if not config:
        return ""
    tokens = _tokenize_iast(value)
    output: list[str] = []
    index = 0
    while index < len(tokens):
        kind, token = tokens[index]
        if kind == "consonant":
            output.append(config["consonants"].get(token, token))
            if index + 1 < len(tokens) and tokens[index + 1][0] == "vowel":
                vowel = tokens[index + 1][1]
                output.append(config["matras"].get(vowel, ""))
                index += 2
                continue
            # IAST writes every pronounced vowel.  A consonant without a
            # following vowel is therefore a dead consonant or conjunct.
            output.append(config["virama"])
        elif kind == "vowel":
            output.append(config["vowels"].get(token, token))
        elif kind == "anusvara":
            output.append(config["anusvara"])
        elif kind == "visarga":
            output.append(config["visarga"])
        elif kind == "avagraha":
            output.append(config["avagraha"])
        else:
            output.append(token)
        index += 1
    return unicodedata.normalize("NFC", "".join(output))


def _has_native_script(value: str, lang: str) -> bool:
    script = _LANG_SCRIPT.get(lang)
    ranges = _INDIC_SCRIPT_RANGES.get(script or "", ())
    return any(any(start <= ord(character) <= end for start, end in ranges) for character in value)


def _contains_iast_residue(value: str) -> bool:
    return any(character in _IAST_LATIN_MARKS for character in value.lower())


def _sanscript_scheme(lang: str) -> str:
    if sanscript is None:
        return ""
    constant_names = {
        "hi": ("DEVANAGARI",), "mr": ("DEVANAGARI",), "ne": ("DEVANAGARI",), "sa": ("DEVANAGARI",),
        "gu": ("GUJARATI",), "bn": ("BENGALI",), "ta": ("TAMIL",), "te": ("TELUGU",),
        "kn": ("KANNADA",), "ml": ("MALAYALAM",), "pa": ("GURMUKHI",), "or": ("ORIYA", "ODIA"),
    }
    for constant_name in constant_names.get(lang, ()):
        value = getattr(sanscript, constant_name, "")
        if value:
            return value
    return LANGUAGES.get(lang, {}).get("scheme", "")


@lru_cache(maxsize=1024)
def localize_sanskrit(pair: tuple[str, str], lang: str) -> str:
    """Return a Sanskrit proper name in the selected script, never Latin IAST."""
    iast, english_name = pair
    if lang == "en" or lang not in LANGUAGES:
        return english_name

    scheme_name = _sanscript_scheme(lang)
    if transliterate and sanscript and scheme_name:
        try:
            translated = unicodedata.normalize("NFC", transliterate(iast, sanscript.IAST, scheme_name)).strip()
            if translated and _has_native_script(translated, lang) and not _contains_iast_residue(translated):
                return translated
        except Exception:
            pass

    translated = _fallback_iast_to_indic(iast, lang)
    if translated and _has_native_script(translated, lang):
        return translated
    return english_name


def join_localized(parts: Iterable[tuple[str, str] | str], lang: str, separator: str = " ") -> str:
    out: list[str] = []
    for part in parts:
        out.append(localize_sanskrit(part, lang) if isinstance(part, tuple) else str(part))
    return separator.join(out)


